<include file="Public:header"/>	<style type="text/css">		.time{color: green;float: left;margin-right: 20px;}		.content{height: 50px;}		.content-desc{float: left;}		.name{margin-bottom: 5px;}	</style>	<form id="myform" method="post" action="{pigcms{:U('position_audit')}" enctype="multipart/form-data" frame="true" refresh="true">		<input type="hidden" name="position_id" value="{pigcms{$detail.position_id}">		<table cellpadding="0" cellspacing="0" class="frame_form" width="100%">			<tr>				<th width="15%">姓名</th>				<td width="35%">{pigcms{$detail.name}</td>				<th width="15%">性别</th>				<td width="35%"><if condition="$detail['sex'] eq 1">男<elseif condition="$detail['sex'] eq 2"/>女<else/>未知</if></td>			</tr>			<tr>				<th width="15%">手机号</th>				<td width="35%">{pigcms{$detail.phone}</td>				<th width="15%">学历</th>				<td width="35%">{pigcms{$detail.qualifications}</td>			</tr>			<tr>				<th width="15%">工作时间</th>				<td width="35%">{pigcms{$detail.work_years}</td>				<th width="15%">期望职位</th>				<td width="35%">{pigcms{$detail.position_name}</td>			</tr>			<tr>				<th width="15%">期望薪资</th>				<td width="35%">{pigcms{$detail.salary}</td>				<th width="15%">求职区域</th>				<td width="35%">{pigcms{$detail.area}</td>			</tr>			<tr>				<th width="15%">工作经历</th>				<td colspan="3">					<if condition="$detail['work_experience']">					<volist name="detail.work_experience" id="vo">						<div class="content">							<div class="time">								<if condition="$vo['end_time']">								{pigcms{$vo.start_time|date='Y-m-d',###} 至 {pigcms{$vo.end_time|date='Y-m-d',###}								<else/>								{pigcms{$vo.start_time|date='Y-m-d',###} 至今								</if>							</div>							<div class="content-desc">								<div class="name">{pigcms{$vo.name}</div>								<div class="desc">{pigcms{$vo.desc}</div>							</div>						</div>					</volist>					<else/>					暂无					</if>				</td>			</tr>			<tr>				<th width="15%">教育经历</th>				<td colspan="3">					<if condition="$detail['education_experience']">					<volist name="detail.education_experience" id="vo">						<div class="content">							<div class="time">								<if condition="$vo['end_time']">								{pigcms{$vo.start_time|date='Y-m-d',###} 至 {pigcms{$vo.end_time|date='Y-m-d',###}								<else/>								{pigcms{$vo.start_time|date='Y-m-d',###} 至今								</if>							</div>							<div class="content-desc">								<div class="name">{pigcms{$vo.name}</div>								<div class="desc">{pigcms{$vo.desc}</div>							</div>						</div>					</volist>					<else/>					暂无					</if>				</td>			</tr>						<tr>				<th width="15%">个人简介</th>				<td width="35%" colspan="3">{pigcms{$detail.self_introduction}</td>			</tr>			<tr>				<th width="15%">是否隐藏</th>				<td width="35%" colspan="3">					<span class="cb-enable">						<label class="cb-enable <if condition="$detail['is_hide'] eq 1">selected</if>">							<span>是</span>							<input type="radio" name="is_hide" value="1" <if condition="$detail['is_hide'] eq 1">checked="checked</if>">						</label>					</span>					<span class="cb-disable">						<label class="cb-disable  <if condition="$detail['is_hide'] eq 0">selected</if>">							<span>否</span>							<input type="radio" name="is_hide" value="0"  <if condition="$detail['is_hide'] eq 0">checked="checked</if>">						</label>					</span>				</td>			</tr>		</table>		<div class="btn hidden">			<input type="submit" name="dosubmit" id="dosubmit" value="提交" class="button" />			<input type="reset" value="取消" class="button" />		</div>	</form>	<script type="text/javascript">		$("input[name=is_hide]").click(function (argument) {			var is_hide = $("input[name=is_hide]:checked").val();			$.post('{pigcms{:U("ajax_change_resume_status")}',{'is_hide':is_hide,id:'{pigcms{$detail.resume_id}'},function(res){				console.log(res)			},'json');		})	</script><include file="Public:footer"/>